          throw normalizeHttpError(error, this.logger);
        }),
        this.converter.pipeable(CUSTOMER_TICKETING_FILE_NORMALIZER)
      );
  }

  protected getDownloadAttachmentEndpoint(
    customerId: string,
    ticketId: string,
    eventCode: string,
    attachmentId: string
  ): string {
    return this.occEndpoints.buildUrl('downloadAttachment', {
      urlParams: {
        customerId,
        ticketId,
        eventCode,
        attachmentId,
      },
    });
  }
}

