      .set('id_token', encodeURIComponent(idToken))
      .set('baseSite', encodeURIComponent(baseSite));

    return this.http
      .post<Partial<AuthToken> & { expires_in?: number }>(url, params)
      .pipe(
        catchError((error: any) => {
          throw normalizeHttpError(error, this.logger);
        })
      );
  }
}

