  deleteAddress$: Observable<
    | OrgUnitActions.DeleteAddressSuccess
    | OrgUnitActions.DeleteAddressFail
    | OrganizationActions.OrganizationClearData
  > = createEffect(() =>
    this.actions$.pipe(
      ofType(OrgUnitActions.DELETE_ADDRESS),
